package com.badrulamin.University_Management.service; import com.badrulamin.University_Management.exception.ResourceNotFoundException;  import com.badrulamin.University_Management.entity.AdmissionResult; import com.badrulamin.University_Management.repository.AdmissionResultRepository; import lombok.RequiredArgsConstructor; import org.springframework.stereotype.Service;  import org.springframework.data.domain.Page; import org.springframework.data.domain.Pageable; import java.util.List;  @Service @RequiredArgsConstructor public class AdmissionResultService {      private final AdmissionResultRepository admissionResultRepository;      public Page<AdmissionResult> findAll(Pageable pageable) {         return admissionResultRepository.findAll(pageable);     }      public AdmissionResult findById(Long id) {         return admissionResultRepository.findById(id)                 .orElseThrow(() -> new ResourceNotFoundException("AdmissionResult", "id", id));     }      public AdmissionResult save(AdmissionResult admissionResult) {         return admissionResultRepository.save(admissionResult);     }      public AdmissionResult update(Long id, AdmissionResult admissionResult) {         findById(id);         admissionResult.setId(id);         return admissionResultRepository.save(admissionResult);     }      public void delete(Long id) {         findById(id);         admissionResultRepository.deleteById(id);     } }